from pathlib import Path
import json, re, html, urllib.parse
import markdown

ROOT=Path(__file__).resolve().parents[1]
scenarios=json.loads((ROOT/'scenarios.json').read_text(encoding='utf-8'))
reports=[json.loads((ROOT/'reports'/f"{s['id']}.json").read_text(encoding='utf-8')) for s in scenarios]
e=lambda v:html.escape(str(v),quote=True)
status={'matches_listed_constraints':'满足','needs_confirmation':'待确认','incompatible':'不满足','pass':'满足','fail':'不满足','unknown':'待确认'}
def local_href(value):
    p=Path(value)
    try:return urllib.parse.quote(p.relative_to(ROOT).as_posix(),safe='/')
    except ValueError:return p.as_uri() if p.is_absolute() else value
def render_md(text):
    result=markdown.markdown(html.escape(text,quote=False),extensions=['tables','fenced_code'])
    def link(m):
        href=html.unescape(m.group(1))
        if href.startswith('file:///'):href=local_href(urllib.parse.unquote(href[8:]))
        elif re.match(r'^[A-Za-z]:[/\\]',href):href=local_href(urllib.parse.unquote(href))
        elif not re.match(r'^(https?://|#|[^:]*$)',href):href='#'
        return 'href="'+e(href)+'"'
    return re.sub(r'href="([^"]*)"',link,result)
def power_chart(report):
    need=report['analysis']['requirements']['calculations'][0]['requiredContinuousW']; temp=next(c['value'] for c in report['analysis']['requirements']['constraints'] if c['field']=='temperature_c')
    focus=[c for c in report['analysis']['candidates'] if c['productId'] in ['SDR-240-24','SDR-480-24','CP20.241-R2']]
    height=70+len(focus)*102; output=f'<svg viewBox="0 0 650 {height}" role="img" aria-label="本工况连续功率、峰值和需求功率"><text x="0" y="20">{temp}℃下的功率核对</text><line x1="{180+need/720*350}" x2="{180+need/720*350}" y1="35" y2="{height-20}" stroke="#b52828" stroke-dasharray="5 4"/><text x="{184+need/720*350}" y="42">需要{need}W连续能力</text>'
    for i,c in enumerate(focus):
        y=72+i*102;p=c.get('power',{});output+=f'<text x="0" y="{y}" class="model">{e(c["productId"])}</text><text x="0" y="{y+20}" fill="{("#137058" if c["status"]=="matches_listed_constraints" else "#b52828")}">{status[c["status"]]}</text>'
        for j,(label,key,color) in enumerate([('额定','ratedW','#99acba'),('连续','verifiedContinuousW','#137058'),('峰值','peakW','#c49836')]):
            value=p.get(key);yy=y-16+j*23;w=(value or 0)/720*350;output+=f'<text x="144" y="{yy+14}">{label}</text><rect x="180" y="{yy}" width="{w}" height="17" fill="{color}"/><text x="{185+w}" y="{yy+14}">{value if value is not None else "未知"}W{(" / "+str(p.get("peakDurationS"))+"s") if key=="peakW" and value is not None else ""}</text>'
    return output+'</svg>'
def width_chart(report):
    products={p['id']:p for p in report['catalogSnapshot']['products']};focus=[c for c in report['analysis']['candidates'] if c['productId'] in ['SDR-240-24','SDR-480-24','CP20.241-R2']];height=90+len(focus)*70
    output=f'<svg viewBox="0 0 650 {height}" role="img" aria-label="本体宽度和65毫米上限"><text x="0" y="20">本体尺寸核对</text><line x1="{180+65/100*350}" x2="{180+65/100*350}" y1="36" y2="{height-15}" stroke="#b52828" stroke-dasharray="5 4"/><text x="{184+65/100*350}" y="47">本体上限65mm</text>'
    for i,c in enumerate(focus):
        p=products[c['productId']];width=p['parameters']['width_mm'];maximum=width+p.get('widthToleranceMm',0);y=76+i*70;check=next(k for k in c['checks'] if k['field']=='width_mm');color='#137058' if check['status']=='pass' else '#b52828';output+=f'<text x="0" y="{y+17}" class="model">{e(c["productId"])}</text><rect x="180" y="{y}" width="{maximum/100*350}" height="26" fill="{color}"/><text x="{185+maximum/100*350}" y="{y+18}">{maximum:g}mm</text><text x="180" y="{y+46}" fill="#596e7f">标称{width:g}mm'+(f'，公差±{p["widthToleranceMm"]:g}mm' if p.get('widthToleranceMm') else '，未披露尺寸公差')+'</text>'
    return output+'</svg>'
def scene(s,r):
    selected=[c for c in r['analysis']['candidates'] if c['productId'] in ['SDR-240-24','SDR-480-24','CP20.241-R2']];need=r['analysis']['requirements']['calculations'][0]['requiredContinuousW'];qualified=r['conclusion']['qualified'];headline=('本轮合格候选：'+('SDR-240-24' if s['id']=='initial' else 'CP20.241-R2 等4个型号')) if qualified else '本快照没有合格候选'
    result=f'<section class="scene" id="scene-{s["id"]}"><div class="result"><h2>{e(s["title"])}：{e(headline)}</h2><p>持续负载{s["loadW"]}W × 1.2 = {need}W连续需求。环境温度{s["tempC"]}℃。资料库{e(r["catalog"]["version"])}。</p><p>{("额定连续240W满足216W。尺寸按63mm + 1mm公差校验。" if s["id"]=="initial" else "SDR-240-24只有240W连续能力。360W峰值限3秒。SDR-480-24本体85.5mm，超过65mm。" if s["id"]=="changed" else "资料库从30个增至39个真实型号。CP20.241-R2在55℃有480W额定连续能力，宽48mm，具备DC OK继电器。")}</p><a href="{e(local_href(s["report"]["htmlPath"]))}">打开完整交互报告</a>　<a href="reports/{s["id"]}.json">查看同一份JSON</a></div><div class="engineering-charts"><article>{power_chart(r)}<p>连续能力按额定降额曲线核验。峰值另列。灰色表示标称额定值。</p></article><article>{width_chart(r)}<p>安装间距另计。已知机械公差按上界比较。</p></article></div><h3>关键候选核对</h3><div class="table-scroll"><table><thead><tr><th>型号</th><th>结论</th><th>主要依据</th></tr></thead><tbody>'
    for c in selected:
        reasons='；'.join(k['label']+'：'+k['actual'] for k in c['checks'] if k['status']!='pass') or '全部已列条件通过。仍需工程师完成应用复核。'
        result+=f'<tr><th>{e(c["productId"])}</th><td class="{c["status"]}">{status[c["status"]]}</td><td>{e(reasons)}</td></tr>'
    result+='</tbody></table></div><details><summary>展开全部型号的核对矩阵和逐项证据</summary><div class="controls"><label>型号 <input type="search" data-filter placeholder="输入型号"></label><label>结果 <select data-status><option value="">全部</option><option value="matches_listed_constraints">满足</option><option value="needs_confirmation">待确认</option><option value="incompatible">不满足</option></select></label><span data-count></span></div><div class="table-scroll"><table data-matrix><thead><tr><th>型号</th><th>结论</th><th>功率</th><th>宽度</th><th>继电器</th><th>安装</th><th>资料版本</th></tr></thead><tbody>'
    for c in r['analysis']['candidates']:
        fields=['output_power_w','width_mm','dc_ok','orientation'];checks={k['field']:k for k in c['checks']};source=next((k.get('source') for k in c['checks'] if k.get('source')),None)
        result+=f'<tr data-model="{e(c["productId"].lower())}" data-status="{c["status"]}"><th><a href="#proof-{s["id"]}-{e(c["productId"])}">{e(c["productId"])}</a></th><td class="{c["status"]}">{status[c["status"]]}</td>'+''.join(f'<td class="{checks[f]["status"]}">{status[checks[f]["status"]]}<small>{e(checks[f]["actual"])}</small></td>' for f in fields)+f'<td>{e(source["version"] if source else "缺失")}</td></tr>'
    result+='</tbody></table></div>'
    for c in r['analysis']['candidates']:
        result+=f'<details id="proof-{s["id"]}-{e(c["productId"])}"><summary>{e(c["productId"])}：{status[c["status"]]}</summary><div class="table-scroll"><table><thead><tr><th>条件</th><th>要求</th><th>资料值</th><th>结果</th><th>原件证据</th></tr></thead><tbody>'
        for k in c['checks']:
            source=k.get('source');ref=f'<a href="{e(local_href(source["file"]))}#page={k.get("page",1)}">{e(source["id"])} · {e(source["version"])} · PDF第{k.get("page","见原件")}页</a><br>' if source else '资料缺失。'
            result+=f'<tr><th>{e(k["label"])}</th><td>{e(k["expected"])}</td><td>{e(k["actual"])}</td><td class="{k["status"]}">{status[k["status"]]}</td><td>{ref}{e(k["quote"])}<br>{e(k["reason"])}</td></tr>'
        result+='</tbody></table></div></details>'
    return result+f'</details><p class="snapshot">本轮快照SHA256：{r["catalog"]["revision"]}</p></section>'

