page+='<script id="scenario-data" type="application/json">'+safe+'</script><script>const scenes=[...document.querySelectorAll(".scene")],links=[...document.querySelectorAll("[data-scene]")];function show(id){for(const p of scenes)p.hidden=p.id!=="scene-"+id;for(const a of links)a.setAttribute("aria-current",String(a.dataset.scene===id));}for(const a of links)a.addEventListener("click",e=>{e.preventDefault();show(a.dataset.scene)});show("initial");for(const s of scenes){const q=s.querySelector("[data-filter]"),st=s.querySelector("[data-status]"),rows=[...s.querySelectorAll("[data-matrix] tbody tr")];const f=()=>{let n=0;for(const r of rows){r.hidden=!r.dataset.model.includes(q.value.toLowerCase())||(st.value&&r.dataset.status!==st.value);if(!r.hidden)n++}s.querySelector("[data-count]").textContent=n+"个型号"};q.addEventListener("input",f);st.addEventListener("change",f);f()}const answers=[...document.querySelectorAll(".raw-answer")],buttons=[...document.querySelectorAll("[data-arm]")].filter(b=>b.tagName==="BUTTON");let arm="c";function answer(){const repeat=document.querySelector("#repeat")?.value,stage=document.querySelector("#stage")?.value;for(const a of answers)a.hidden=a.dataset.arm!==arm||a.dataset.repeat!==repeat||a.dataset.stage!==stage;for(const b of buttons)b.classList.toggle("active",b.dataset.arm===arm)}for(const b of buttons)b.addEventListener("click",()=>{arm=b.dataset.arm;answer()});document.querySelector("#repeat")?.addEventListener("change",answer);document.querySelector("#stage")?.addEventListener("change",answer);answer();document.addEventListener("click",e=>{const a=e.target.closest("a[href^=\\"#proof-\\"]");if(a){const t=document.getElementById(a.getAttribute("href").slice(1));if(t){t.open=true;t.closest(".scene").querySelector("details").open=true;}}});</script></html>'
(ROOT/'index.html').write_text(page,encoding='utf-8')
